"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Slider } from "@/components/ui/slider"

type VideoFrameCopy = {
  "controls.label": string
  "controls.play": string
  "controls.pause": string
  "controls.scrubber": string
}

export function VideoFrame({
  scenes,
  copy,
  sceneSeconds = 6,
  className,
}: {
  scenes: readonly React.ReactNode[]
  copy: VideoFrameCopy
  sceneSeconds?: number
  className?: string
}) {
  const total = scenes.length
  const last = Math.max(total - 1, 0)
  // Starts paused (reduced motion): scenes advance only after the viewer presses play.
  const [playing, setPlaying] = React.useState(false)
  const [scene, setScene] = React.useState(0)

  React.useEffect(() => {
    if (!playing) return
    if (scene >= last) {
      setPlaying(false)
      return
    }
    const timer = window.setTimeout(() => setScene(scene + 1), sceneSeconds * 1000)
    return () => window.clearTimeout(timer)
  }, [playing, scene, last, sceneSeconds])

  return (
    <div data-slot="video-frame" data-aspect="16:9" data-start="paused" data-playing={playing} className={cn("mx-auto flex w-full flex-col overflow-hidden rounded-lg border border-border bg-background text-foreground", className)}>
      <main data-slot="video-stage" className="aspect-video w-full overflow-hidden">
        {scenes[scene]}
      </main>
      <section data-slot="video-controls" aria-label={copy["controls.label"]} className="flex items-center gap-3 border-t border-border bg-muted px-3 py-2 text-muted-foreground">
        <Button variant="ghost" size="sm" isDisabled={total < 2} onPress={() => setPlaying(!playing)}>
          {playing ? copy["controls.pause"] : copy["controls.play"]}
        </Button>
        <Slider aria-label={copy["controls.scrubber"]} minValue={0} maxValue={last} step={1} value={scene} isDisabled={total < 2} onChange={(value: number | number[]) => setScene(Array.isArray(value) ? value[0] ?? 0 : value)} className="flex-1" />
        <span data-slot="video-scene-count" className="text-sm tabular-nums">
          {Math.min(scene + 1, total)} / {total}
        </span>
      </section>
    </div>
  )
}
